    def get_author(self):
        return self.author

    def get_publication_year(self):
        return self.publication_year

    def set_title(self, new_title):
        self.title = new_title

    def set_author(self, new_author):
        self.author = new_author

    def set_publication_year(self, new_year):
        if isinstance(new_year, int) and new_year > 0:
            self.publication_year = new_year
        else:
            raise ValueError("Publication year must be a positive integer.")

    def is_published_before(self, other_year):
        return self.publication_year < other_year

    def is_published_after(self, other_year):
        return self.publication_year > other_year

    def is_same_year(self, other_year):
        return self.publication_year == other_year
